package com.suresh.lifeos;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;import java.util.*;
public class AlarmReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){long id=i.getLongExtra("task_id",-1);int alarmCode=i.getIntExtra("alarm_code",(int)id);Intent open=new Intent(c,MainActivity.class);open.putExtra("task_id",id);open.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent pi=PendingIntent.getActivity(c,alarmCode,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,LifeApp.CH):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Suresh Life OS").setContentText("Private reminder due now — unlock to view.").setVisibility(Notification.VISIBILITY_SECRET).setCategory(Notification.CATEGORY_ALARM).setPriority(Notification.PRIORITY_MAX).setAutoCancel(true).setContentIntent(pi);c.getSystemService(NotificationManager.class).notify(alarmCode,b.build());scheduleUpcoming(c);}
 public static void scheduleToday(Context c){scheduleUpcoming(c);}
 public static void scheduleUpcoming(Context c){Store s=Store.get(c);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);long now=System.currentTimeMillis();for(int off=0;off<14;off++){LocalDate day=LocalDate.now().plusDays(off);int dow=day.getDayOfWeek().getValue();for(Map<String,String>x:s.q("SELECT * FROM tasks WHERE active=1")){String days=x.get("days");if(days==null||!Arrays.asList(days.split(",")).contains(String.valueOf(dow)))continue;try{int min=Integer.parseInt(x.get("start_min"));ZonedDateTime z=day.atTime(min/60,min%60).atZone(ZoneId.systemDefault());long when=z.toInstant().toEpochMilli();if(when<=now)continue;long id=Long.parseLong(x.get("id"));int req=(int)((id*1009L+day.toEpochDay())&0x7fffffff);Intent i=new Intent(c,AlarmReceiver.class).putExtra("task_id",id).putExtra("alarm_code",req);PendingIntent p=PendingIntent.getBroadcast(c,req,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT>=31&&!a.canScheduleExactAlarms())a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);else a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}catch(Exception ignored){}}}OverdueReceiver.scheduleUpcoming(c);}
}
